def value(page,ref):return page.evaluate('(ref)=>WorkbookEngine.value(activeWorkbook.book,activeWorkbook.book.sheets[0].cells.get(ref))',ref)
def formula(page,ref):return page.evaluate('(ref)=>WorkbookEngine.child(activeWorkbook.book.sheets[0].cells.get(ref),"f")?.textContent',ref)
